// Patrón: metadata privada con WeakMap
// Util para asociar datos a objetos sin modificarlos

const _datos = new WeakMap();

function crearNodo(valor) {
  const nodo = { valor };
  _datos.set(nodo, { visitado: false, profundidad: 0 });
  return nodo;
}

function marcarVisitado(nodo, profundidad) {
  const meta = _datos.get(nodo);
  meta.visitado = true;
  meta.profundidad = profundidad;
}

function estaVisitado(nodo) {
  return _datos.get(nodo)?.visitado ?? false;
}

const n1 = crearNodo('A');
const n2 = crearNodo('B');

marcarVisitado(n1, 0);
marcarVisitado(n2, 1);

console.log('n1 visitado:', estaVisitado(n1)); // true
console.log('n2 profundidad:', _datos.get(n2).profundidad); // 1
console.log('n1.visitado directo:', n1.visitado); // undefined — es privado

// WeakSet para tracking de objetos procesados
// Evita procesar el mismo objeto dos veces en un flujo

const procesados = new WeakSet();

function procesar(objeto) {
  if (procesados.has(objeto)) {
    console.log('Ya procesado:', objeto.id);
    return objeto;
  }

  // Simula procesamiento
  const resultado = { ...objeto, procesado: true, timestamp: Date.now() };
  procesados.add(objeto);
  console.log('Procesando:', objeto.id);
  return resultado;
}

const item1 = { id: 1, datos: 'abc' };
const item2 = { id: 2, datos: 'xyz' };

procesar(item1); // 'Procesando: 1'
procesar(item2); // 'Procesando: 2'
procesar(item1); // 'Ya procesado: 1'

console.log('¿item1 procesado?', procesados.has(item1)); // true

