function crearFormulario() {
  // Usamos el formulario mismo como clave del WeakMap
  const _metadataStore = new WeakMap();

  const formulario = {
    validar(campo, valor, regla) {
      if (!_metadataStore.has(formulario)) {
        _metadataStore.set(formulario, { errores: {} });
      }
      const meta = _metadataStore.get(formulario);
      if (!regla(valor)) {
        meta.errores[campo] = `Error en ${campo}`;
      } else {
        delete meta.errores[campo];
      }
    },
    tieneErrores() {
      const meta = _metadataStore.get(formulario);
      if (!meta) return false;
      return Object.keys(meta.errores).length > 0;
    },
    obtenerErrores() {
      return _metadataStore.get(formulario)?.errores ?? {};
    },
  };

  return formulario;
}

const form = crearFormulario();

form.validar('nombre', 'Ana', v => v.length > 0);       // OK
form.validar('email', 'no-es-email', v => v.includes('@')); // Error
form.validar('edad', 25, v => v >= 18);                    // OK

const tieneErrores = form.tieneErrores();
const errores = form.obtenerErrores();

console.log('Tiene errores:', tieneErrores);
console.log('Errores:', errores);

function esCircular(obj) {
  const visitados = new WeakSet();

  function recorrer(valor) {
    if (typeof valor !== 'object' || valor === null) return false;
    if (visitados.has(valor)) return true; // ¡Circular!
    visitados.add(valor);
    for (const prop of Object.values(valor)) {
      if (recorrer(prop)) return true;
    }
    return false;
  }

  return recorrer(obj);
}

const obj1 = { a: 1, b: { c: 2 } };
const obj2 = { a: 1 };
obj2.self = obj2; // Referencia circular

const esCircular1 = esCircular(obj1); // false
const esCircular2 = esCircular(obj2); // true

console.log('obj1 circular:', esCircular1);
console.log('obj2 circular:', esCircular2);
